<?php require_once __DIR__.'/../src/App.php'; require_once __DIR__.'/../src/LoanView.php'; require_once __DIR__.'/../src/Repository.php';
$path=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH) ?: '/';
$staticRoot=realpath(__DIR__.'/../static');$requested=realpath($staticRoot.'/'.ltrim(substr($path,8),'/'));
if(str_starts_with($path,'/static/') && $staticRoot && $requested && str_starts_with($requested,$staticRoot.DIRECTORY_SEPARATOR) && is_file($requested)){ $types=['css'=>'text/css; charset=utf-8','js'=>'application/javascript; charset=utf-8','webmanifest'=>'application/manifest+json','svg'=>'image/svg+xml'];$ext=strtolower(pathinfo($requested,PATHINFO_EXTENSION));header('Content-Type',$types[$ext]??'application/octet-stream');readfile($requested);exit; }
$action=$_POST['action']??'';
if($_SERVER['REQUEST_METHOD']==='POST' && in_array($action,['contribution','reset_contribution'],true)){try{$repo=new Repository(Database::connection());$p=(int)$_POST['participant_id'];$y=(int)$_POST['year'];$m=(int)$_POST['month'];if($action==='contribution'){$repo->recordContribution($p,$y,$m,(float)($_POST['amount']??0));$q=Database::connection()->prepare('SELECT COUNT(*) FROM contributions WHERE participant_id=? AND year=? AND amount_paid<amount_due');$q->execute([$p,$y]);$notice=((int)$q->fetchColumn()===0&&$m===11)?'paz_salvo':'contribution_saved';}else{$repo->resetContribution($p,$y,$m);$notice='contribution_reset';}}catch(Throwable $e){$notice=str_contains($e->getMessage(),'completo')?'contribution_complete':'contribution_error';}$back=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH)?:'/';$query=$_GET;$query['year']=$y;$query['participant']=$_GET['participant']??'';$query['notice']=$notice;header('Location: '.$back.'?'.http_build_query($query));exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && $action==='loan_update'){$db=Database::connection();$id=(int)$_POST['loan_id'];$principal=(float)$_POST['principal'];$term=(int)$_POST['term_months'];$q=$db->prepare('SELECT monthly_rate,start_date FROM loans WHERE id=? AND status="active"');$q->execute([$id]);$old=$q->fetch();if($old){$db->beginTransaction();$db->prepare('UPDATE loans SET principal=?,term_months=? WHERE id=?')->execute([$principal,$term,$id]);$rows=Finance::amortization($principal,(float)$old['monthly_rate'],$term,new DateTimeImmutable($old['start_date']));$q=$db->prepare('SELECT id,installment_number,paid_amount FROM loan_installments WHERE loan_id=? ORDER BY installment_number');$q->execute([$id]);$existing=$q->fetchAll();$update=$db->prepare('UPDATE loan_installments SET due_date=?,principal_amount=?,interest_amount=?,total_amount=?,paid_amount=LEAST(?,?) WHERE id=?');$insert=$db->prepare('INSERT INTO loan_installments(loan_id,installment_number,due_date,principal_amount,interest_amount,total_amount,paid_amount) VALUES(?,?,?,?,?,?,0)');foreach($rows as $idx=>$row){$oldRow=$existing[$idx]??null;if($oldRow)$update->execute([$row['due_date'],$row['principal'],$row['interest'],$row['total'],$oldRow['paid_amount'],$row['total'],$oldRow['id']]);else $insert->execute([$id,$row['number'],$row['due_date'],$row['principal'],$row['interest'],$row['total']]);}foreach(array_slice($existing,count($rows)) as $extra){if((float)$extra['paid_amount']<=0)$db->prepare('DELETE FROM loan_installments WHERE id=? AND paid_amount=0')->execute([$extra['id']]);}$db->commit();}header('Location: /loans?notice=loan_updated');exit;}
if($_SERVER['REQUEST_METHOD']==='POST' && in_array($action,['loan_cancel','loan_update','loan_create'],true)){$db=Database::connection();$repo=new Repository($db);if($action==='loan_cancel'){$repo->cancelLoan((int)$_POST['loan_id']);header('Location: /loans');exit;}if($action==='loan_update'){$id=(int)$_POST['loan_id'];$principal=(float)$_POST['principal'];$term=(int)$_POST['term_months'];$s=$db->prepare('UPDATE loans SET principal=?,term_months=? WHERE id=? AND status="active"');$s->execute([$principal,$term,$id]);header('Location: /loans');exit;}if($action==='loan_create'){$p=(int)$_POST['participant_id'];$type=$_POST['loan_type']==='REFERRED'?'REFERRED':'PARTICIPANT';$rate=$type==='REFERRED'?0.10:0.05;$s=$db->prepare('INSERT INTO loans(participant_id,principal,monthly_rate,term_months,start_date,loan_type,referred_name,referred_document) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$p,(float)$_POST['principal'],$rate,(int)$_POST['term_months'],$_POST['start_date'],$type,trim($_POST['referred_name']??''),trim($_POST['referred_document']??'')]);$id=(int)$db->lastInsertId();$rows=Finance::amortization((float)$_POST['principal'],$rate,(int)$_POST['term_months'],new DateTimeImmutable($_POST['start_date']));$i=$db->prepare('INSERT INTO loan_installments(loan_id,installment_number,due_date,principal_amount,interest_amount,total_amount) VALUES(?,?,?,?,?,?)');foreach($rows as $row)$i->execute([$id,$row['number'],$row['due_date'],$row['principal'],$row['interest'],$row['total']]);header('Location: /loans');exit;}}
if($_SERVER['REQUEST_METHOD']==='POST' && in_array($action,['participant_update','participant_toggle','participant_delete'],true)){try{$db=Database::connection();$id=(int)$_POST['participant_id'];if($action==='participant_update'){(new Repository($db))->updateParticipant($id,$_POST);$notice='participant_updated';}elseif($action==='participant_toggle'){(new Repository($db))->setParticipantActive($id,!((int)($_POST['active']??0)));$notice='participant_updated';}else{(new Repository($db))->deleteParticipant($id);$notice='participant_deleted';}}catch(Throwable $e){$notice=$action==='participant_toggle'?'participant_loan_blocked':'participant_error';$detail=$e->getMessage();}$q=['notice'=>$notice];if(isset($detail))$q['detail']=$detail;header('Location: /participants?'.http_build_query($q));exit;}
if(preg_match('#^/loans/(\d+)$#',$path,$match)){
  $db=Database::connection();
