if($path==='/participants'){$ids=Database::connection()->query('SELECT id,full_name,document,phone,email FROM participants ORDER BY active DESC,full_name')->fetchAll();$n=0;$html=preg_replace_callback('#<article class="card">(.*?)</article>#s',function($m)use(&$n,$ids){$p=$ids[$n++]??[];$id=(int)($p['id']??0);return '<article class="card">'.$m[1].'<details><summary>Editar</summary><form method="post"><input type="hidden" name="action" value="participant_update"><input type="hidden" name="participant_id" value="'.$id.'"><input name="full_name" value="'.htmlspecialchars($p['full_name']??'',ENT_QUOTES).'" required><input name="document" value="'.htmlspecialchars($p['document']??'',ENT_QUOTES).'" required><input name="phone" value="'.htmlspecialchars($p['phone']??'',ENT_QUOTES).'" placeholder="Teléfono"><input name="email" value="'.htmlspecialchars($p['email']??'',ENT_QUOTES).'" placeholder="Correo"><button>Guardar cambios</button></form></details><div class="actions"><form method="post"><input type="hidden" name="action" value="participant_toggle"><input type="hidden" name="participant_id" value="'.$id.'"><button>Desactivar / Activar</button></form><form method="post"><input type="hidden" name="action" value="participant_delete"><input type="hidden" name="participant_id" value="'.$id.'"><button>Eliminar</button></form></div></article>';},$html);}
